// Арифметика — детермінований код. Модель не рахує суми.
const r = [];
for (const item of $input.all()) {
  const d = item.json;
  const lines = d.lines ?? [];
  const sumLines = Number(lines.reduce((a, l) => a + Number(l.amount || 0), 0).toFixed(2));
  const base = Number(d.amount_base || 0);
  const vat = Number(d.amount_vat || 0);
  const total = Number(d.amount_total || 0);

  const checks = [];
  if (lines.length && Math.abs(sumLines - base) > 0.02)
    checks.push('Сума рядків ' + sumLines.toFixed(2) + ' ≠ сума без ПДВ ' + base.toFixed(2));
  if (Math.abs(base + vat - total) > 0.02)
    checks.push('Без ПДВ + ПДВ ≠ усього (' + (base + vat).toFixed(2) + ' проти ' + total.toFixed(2) + ')');
  const expectVat = Number((base * 0.2).toFixed(2));
  if (vat > 0 && Math.abs(vat - expectVat) > 0.02)
    checks.push('ПДВ не дорівнює 20 % бази (очікували ' + expectVat.toFixed(2) + ')');

  r.push({ json: { ...d, sum_lines: sumLines, arith_errors: checks, arith_ok: checks.length === 0 } });
}
return r;

// Зшиваємо рядки документа з результатами зіставлення.
const doc = $('Арифметична перевірка').first().json;
const cp = $('Контрагент за ЄДРПОУ').first().json;
const m = new Map($input.all().map(i => [Number(i.json.line_no), i.json]));

const lines = (doc.lines ?? []).map((l, ix) => {
  const hit = m.get(ix + 1) ?? {};
  return {
    ...l,
    nomenclature_id: hit.nomenclature_id ?? null,
    match_method: hit.match_method ?? null,
    match_conf: hit.match_conf ?? null,
    candidates: hit.candidates ?? null,
    needs_review: !hit.nomenclature_id || hit.match_conf === 'medium'
  };
});

const unresolved = lines.filter(l => !l.nomenclature_id);
return [{ json: {
  ...doc,
  counterparty_id: cp.id ?? null,
  counterparty_known: Boolean(cp.id),
  lines,
  unresolved_count: unresolved.length,
  needs_llm: unresolved.length > 0
}}];

// Рахунок обліку — РІШЕННЯ. Його ухвалює правило, а не модель.
// Якщо жодне правило не збіглося — документ іде людині, а не «на око».
const doc = $('Зшити рядки з результатами').first().json;
const rules = $input.all().map(i => i.json);
let llm = {};
try {
  const resp = $('Claude — вибір із кандидатів').first().json;
  const parsed = JSON.parse(resp.content?.[0]?.text ?? '{"matches":[]}');
  llm = Object.fromEntries(parsed.matches.map(m => [m.line_no, m]));
} catch (e) { llm = {}; }

const lines = doc.lines.map(l => {
  const guess = llm[l.line_no];
  const nomId = l.nomenclature_id ?? (guess && guess.confidence !== 'low' ? guess.nomenclature_id : null);
  const method = l.match_method ?? (nomId ? 'llm' : null);
  const conf = l.match_conf ?? (guess ? guess.confidence : null);

  const rule = rules.find(r =>
    (!r.match_doc_type || r.match_doc_type === doc.doc_type) &&
    (!r.match_cp_id || r.match_cp_id === doc.counterparty_id) &&
    (!r.match_nom_id || r.match_nom_id === nomId) &&
    (!r.match_name_like || new RegExp(r.match_name_like.replace(/%/g, '.*'), 'i').test(l.raw_name))
  );

  return { ...l,
    nomenclature_id: nomId,
    match_method: method,
    match_conf: conf,
    llm_why: guess ? guess.why : null,
    debit_account: rule ? rule.debit_account : null,
    credit_account: rule ? rule.credit_account : '631',
    needs_review: !nomId || conf !== 'exact' || !rule
  };
});

// Правило рішення. Автоматично проходять лише документи, де НІЧОГО не вгадувалось.
const reasons = [];
if (!doc.arith_ok) reasons.push(doc.arith_errors[0]);
if (!doc.counterparty_known) reasons.push('Контрагента немає в довіднику — потрібне створення');
const unmatched = lines.filter(l => !l.nomenclature_id).length;
if (unmatched) reasons.push(unmatched + ' позиц. не зіставлені з номенклатурою');
const noRule = lines.filter(l => !l.debit_account).length;
if (noRule) reasons.push('Рахунок обліку не визначено правилом');
if (doc.confidence === 'low') reasons.push('Низька якість розпізнавання');
if (Number(doc.amount_total) > Number($env.AUTO_LIMIT_UAH || 100000)) reasons.push('Сума понад ліміт автоматичного проведення');
if (doc.trusted_sender === false) reasons.push('Лист не пройшов SPF/DKIM/DMARC');

const allExact = lines.length > 0 && lines.every(l => l.match_conf === 'exact' && l.debit_account);
const status = reasons.length ? 'review' : (allExact && doc.confidence === 'n/a' ? 'verified' : 'review');

return [{ json: { ...doc, lines, status,
  review_reason: reasons[0] ?? null,
  review_reasons: reasons,
  sla_hours: 4
}}];
